  "checks": [
    {
      "id": "RISK-APPROPRIATE",
      "result": "PASS",
      "severity": "Major",
      "finding": "tasks.md assigns high risk to T-002–T-007 contract, authorization, provider execution and protected verification changes. T-001 and T-008 are medium-risk maintenance and delivery work without new cloud authority."
    },
    {
      "id": "HIGH-CRITICAL-EVIDENCE",
      "result": "PASS",
      "severity": "Critical",
      "finding": "T-002–T-007 each require committed failing tests before implementation, Red→Green evidence and a named independent reviewer verdict in Done When. No critical-risk task is declared."
    },
    {
      "id": "TASK-SIZE",
      "result": "FAIL",
      "severity": "Major",
      "finding": "tasks.md T-006 combines both provider collectors, verification reduction, dependency receipt orchestration, protected registry/evaluator dispatch, schema mirrors and guard projections. These exceed three distinct implementation areas and require independent security-sensitive integration and regression work, making one focused session unrealistic. Split provider observation/reduction from protected profile dispatch and dependency orchestration, with explicit intermediate contracts and blockers."
    },
    {
      "id": "EDGE-CASE-COVERAGE",
      "result": "PASS",
      "severity": "Major",
      "finding": "Functional tasks bind negative scenarios: T-002 AC-004/010 mutation and unsafe input; T-003 AC-005/006 denied approval and replay; T-004/005 AC-002/007 unsupported ownership and destructive changes; T-006 AC-008/009 missing checks and stale observations; T-007 AC-011/012 unauthorized direct invocation and unavailable authentication."
    },
    {
      "id": "TEST-TYPE-MATCH",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-001 AC-001 integration covers inventory checker and CI drivers. Embedded provider/admission tests cross executor and validation boundaries; design.md Unit and Integration Boundaries separates module-level validation from subprocess integration and live sandbox evidence. No standalone test task declares a conflicting test type."
    },
    {
      "id": "ROLLBACK-PLAN",
      "result": "PASS",
      "severity": "Major",
      "finding": "Every high-risk task T-002–T-007 explicitly requires a documented and tested rollback procedure. The shared rollback section requires task-owned byte restoration trials, baseline checks and disabling cloud entry/workflows while preserving historical evidence and native operation identities."
    },
    {
      "id": "SCOPE-DISJOINT",
      "result": "PASS",
      "severity": "Major",
      "finding": "Shared execution tests are ordered T-003→T-004→T-005; T-006 follows both providers before extending their collectors; T-007 follows T-001 and T-006 before suite-driver and packaging changes; T-008 follows T-007 for documentation/version updates. Lifecycle explicitly permits only one implementation task at a time."
    },
    {
      "id": "DEPENDENCY-OVERLAP",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-003 consumes T-002 contracts; provider execution consumes contracts and admission; T-005 explicitly consumes T-004 public CLI decisions and harness; T-006 consumes both provider implementations; T-007 packages their verified integration and foundation suite; T-008 documents and releases the installed deliverable."
    },
    {
      "id": "BUGFIX-DIAGNOSTIC-PATH",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-001 Goal requires diagnosis of the historical stale-line failure before additional fixes. Done When retains the exact failure log, diagnoses the section reference, runs the named foundation regression command and tests removal, relocation, duplicate headings and path escape. Round 1: no prior-round summary."
    }
  ],
  "findings": [
    {
      "check_id": "TASK-SIZE",
      "severity": "Major",
      "task_id": "T-006",
      "finding": "specs/cloud-orchestration/tasks.md T-006 Goal, Planned Files and Done When combine both provider collectors, verification reduction, dependency receipt orchestration, protected registry/evaluator dispatch, schema mirrors and guard projections. This exceeds three distinct implementation areas and is not a realistic single focused session; a single completion gate conflates independently testable security-sensitive changes. Split observation/reduction, protected profile dispatch and dependency orchestration into bounded tasks with explicit contracts and blockers."
    }
  ]
